/* ---------- Language switching ---------- */
function applyLang(lang){
  const baseDict = I18N[lang]||I18N.en;
  const pageExtra = (window.ICM_I18N_PAGE && (window.ICM_I18N_PAGE[lang]||window.ICM_I18N_PAGE.en)) || {};
  const dict = Object.assign({}, baseDict, pageExtra);
  document.documentElement.lang = lang === 'uk' ? 'uk' : lang;
  document.documentElement.dataset.lang = lang;
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const k = el.getAttribute('data-i18n');
    if(dict[k] !== undefined){ el.innerHTML = dict[k]; }
  });
  const cur = document.getElementById('langCurrent');
  if(cur) cur.textContent = lang.toUpperCase();
  document.querySelectorAll('.lang-menu button, .mobile-langs button').forEach(b=>{
    b.setAttribute('aria-current', b.dataset.lang===lang ? 'true':'false');
  });
  try{ localStorage.setItem('icm-lang', lang);}catch(e){}
}

/* ---------- DOM ready ---------- */
document.addEventListener('DOMContentLoaded', ()=>{
  const stored = (()=>{ try{return localStorage.getItem('icm-lang');}catch(e){return null;}})();
  const supported = ['en','ru','uk','pt'];
  applyLang((stored && supported.includes(stored)) ? stored : 'en');

  /* Loader */
  setTimeout(()=>document.getElementById('loader').classList.add('hidden'), 1700);

  /* Year */
  document.getElementById('yr').textContent = new Date().getFullYear();

  /* Header scroll state */
  const header = document.getElementById('header');
  const onScroll=()=>{ header.classList.toggle('is-scrolled', window.scrollY>40); };
  window.addEventListener('scroll', onScroll, {passive:true}); onScroll();

  /* Hero parallax */
  const heroBg = document.getElementById('heroBg');
  const heroTitle = document.getElementById('heroTitle');
  if(heroBg){
    let ticking=false;
    window.addEventListener('scroll', ()=>{
      if(ticking) return;
      requestAnimationFrame(()=>{
        const y = Math.min(window.scrollY*0.35, 200);
        heroBg.style.transform = `translate3d(0, ${y}px, 0) scale(1.05)`;
        if(heroTitle) heroTitle.style.transform = `translate3d(0, ${window.scrollY*0.12}px, 0)`;
        ticking=false;
      });
      ticking=true;
    }, {passive:true});
  }

  /* Hero title reveal */
  setTimeout(()=>{
    document.querySelectorAll('#heroTitle .inner').forEach((el,i)=>{
      el.style.transition = `transform .9s cubic-bezier(.2,.7,.2,1) ${i*0.08}s`;
      el.style.transform = 'translateY(0)';
    });
  }, 1900);

  /* Lang menu */
  const langBtn = document.getElementById('langBtn');
  const langMenu = document.getElementById('langMenu');
  langBtn.addEventListener('click', e=>{ e.stopPropagation(); langMenu.classList.toggle('open'); langBtn.setAttribute('aria-expanded', langMenu.classList.contains('open')); });
  document.addEventListener('click', ()=>{ langMenu.classList.remove('open'); langBtn.setAttribute('aria-expanded','false'); });
  langMenu.addEventListener('click', e=>{
    const b = e.target.closest('button[data-lang]');
    if(!b) return;
    applyLang(b.dataset.lang);
    langMenu.classList.remove('open');
  });
  document.querySelectorAll('.mobile-langs button').forEach(b=>{
    b.addEventListener('click', ()=>{
      applyLang(b.dataset.lang);
      document.getElementById('mobileDrawer').classList.remove('open');
      document.getElementById('menuToggle').classList.remove('open');
    });
  });

  /* Mobile menu */
  const mt = document.getElementById('menuToggle');
  const drawer = document.getElementById('mobileDrawer');
  mt.addEventListener('click', ()=>{
    mt.classList.toggle('open');
    drawer.classList.toggle('open');
    document.body.style.overflow = drawer.classList.contains('open')?'hidden':'';
  });
  drawer.querySelectorAll('a').forEach(a=>a.addEventListener('click', ()=>{
    drawer.classList.remove('open');
    mt.classList.remove('open');
    document.body.style.overflow = '';
  }));

  /* Reveal observer */
  const io = new IntersectionObserver((entries)=>{
    entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }});
  }, {threshold:.12, rootMargin:'0px 0px -60px 0px'});
  document.querySelectorAll('.reveal, .reveal-stagger').forEach(el=>io.observe(el));

  /* Counters */
  const cIo = new IntersectionObserver((entries)=>{
    entries.forEach(e=>{
      if(!e.isIntersecting) return;
      const el = e.target;
      const target = parseInt(el.dataset.counter,10);
      const suffix = el.dataset.suffix||'';
      const dur = 1600;
      const start = performance.now();
      const from = 0;
      const tick = (now)=>{
        const t = Math.min((now-start)/dur, 1);
        const eased = 1-Math.pow(1-t,3);
        const v = Math.round(from + (target-from)*eased);
        el.textContent = v + suffix;
        if(t<1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
      cIo.unobserve(el);
    });
  }, {threshold:.4});
  document.querySelectorAll('[data-counter]').forEach(el=>cIo.observe(el));

  /* Service hover spotlight */
  document.querySelectorAll('.service').forEach(s=>{
    s.addEventListener('mousemove', e=>{
      const r = s.getBoundingClientRect();
      s.style.setProperty('--mx', ((e.clientX-r.left)/r.width*100)+'%');
      s.style.setProperty('--my', ((e.clientY-r.top)/r.height*100)+'%');
    });
  });

  /* FAQ accordion */
  document.querySelectorAll('.faq-item .faq-q').forEach(q=>{
    q.addEventListener('click', ()=>{
      const item = q.parentElement;
      const wasOpen = item.classList.contains('open');
      document.querySelectorAll('.faq-item.open').forEach(i=>i.classList.remove('open'));
      if(!wasOpen) item.classList.add('open');
    });
  });

  /* Modal */
  const modal = document.getElementById('modal');
  const openModal = ()=>{ modal.classList.add('open'); document.body.style.overflow='hidden'; };
  const closeModal = ()=>{ modal.classList.remove('open'); document.body.style.overflow=''; document.getElementById('formSuccess').classList.remove('show'); document.getElementById('leadForm').style.display=''; };
  document.getElementById('openForm').addEventListener('click', openModal);
  document.querySelectorAll('[data-cta="book"]').forEach(b=>{
    b.addEventListener('click', e=>{
      if(b.tagName==='A' && b.getAttribute('href') !== '#contact') return;
      // for service cards opening modal
    });
  });
  document.getElementById('closeModal').addEventListener('click', closeModal);
  modal.addEventListener('click', e=>{ if(e.target===modal) closeModal(); });
  document.addEventListener('keydown', e=>{ if(e.key==='Escape' && modal.classList.contains('open')) closeModal(); });

  /* Form: submit to FormSubmit (POST in background) AND open WhatsApp in parallel */
  document.getElementById('leadForm').addEventListener('submit', e=>{
    e.preventDefault();
    const form = e.target;
    const fd = new FormData(form);
    const lines = [];
    fd.forEach((v,k)=>{ if(!String(k).startsWith('_') && k!=='_honey' && v) lines.push(`${k}: ${v}`); });
    const msg = encodeURIComponent('Iron Custom Motors — new request:\n\n'+lines.join('\n'));
    // 1) Send to backend (no redirect) — note: first time formsubmit needs to be activated by clicking the verification email
    fetch(form.action, { method:'POST', body: fd, mode: 'no-cors' }).catch(()=>{});
    // 2) Open WhatsApp in parallel
    window.open(`https://wa.me/351917961230?text=${msg}`, '_blank');
    // Track event if analytics consented
    if(window.dataLayer){ window.dataLayer.push({event:'form_submit', form:'lead', service: fd.get('service')||''}); }
    form.style.display='none';
    document.getElementById('formSuccess').classList.add('show');
  });

  /* Localized WhatsApp prefill — runs after each language change */
  function refreshWaLinks(){
    const dict = I18N[document.documentElement.dataset.lang||'en']||I18N.en;
    const txt = encodeURIComponent(dict['wa.prefill']||'');
    document.querySelectorAll('a[data-wa]').forEach(a=>{
      const base = 'https://wa.me/351917961230';
      a.href = txt ? `${base}?text=${txt}` : base;
    });
  }
  // hook into applyLang
  const _origApplyLang = applyLang;
  applyLang = function(lang){ _origApplyLang(lang); refreshWaLinks(); };
  refreshWaLinks();

  /* Sticky CTA bar — show after hero scroll */
  const stickyCta = document.getElementById('stickyCta');
  const heroEl = document.getElementById('hero');
  const stickyIo = new IntersectionObserver(([e])=>{
    const past = !e.isIntersecting;
    stickyCta.classList.toggle('show', past);
    document.body.classList.toggle('has-sticky-cta', past);
  }, {threshold:0});
  if(heroEl) stickyIo.observe(heroEl);
  // Track WhatsApp clicks
  document.querySelectorAll('a[data-wa]').forEach(a=>a.addEventListener('click', ()=>{
    if(window.dataLayer) window.dataLayer.push({event:'click_whatsapp'});
  }));

  /* Cookie consent — minimal self-hosted */
  const cookieBanner = document.getElementById('cookieBanner');
  const consent = (()=>{ try{return localStorage.getItem('icm-consent');}catch(e){return null;}})();
  function loadAnalytics(){
    /* === GA4 === */
    const GA_ID = 'G-PJWZKP1CFW';
    if(GA_ID){
      const s = document.createElement('script');
      s.async = true; s.src = `https://www.googletagmanager.com/gtag/js?id=${GA_ID}`;
      document.head.appendChild(s);
      window.dataLayer = window.dataLayer || [];
      function gtag(){dataLayer.push(arguments)}
      window.gtag = gtag;
      gtag('js', new Date());
      gtag('config', GA_ID, {anonymize_ip:true});
    } else {
      window.dataLayer = window.dataLayer || [];
    }
    /* === Meta (Facebook) Pixel === */
    const FB_PIXEL = '1708697916976439';
    if(FB_PIXEL){
      !function(f,b,e,v,n,t,s){if(f.fbq)return;n=f.fbq=function(){n.callMethod?n.callMethod.apply(n,arguments):n.queue.push(arguments)};if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version='2.0';n.queue=[];t=b.createElement(e);t.async=!0;t.src=v;s=b.getElementsByTagName(e)[0];s.parentNode.insertBefore(t,s)}(window,document,'script','https://connect.facebook.net/en_US/fbevents.js');
      fbq('init', FB_PIXEL); fbq('track', 'PageView');
    }
  }
  function showBanner(){
    cookieBanner.classList.add('show');
    document.body.classList.add('has-cookie-banner');
  }
  function hideBanner(){
    cookieBanner.classList.remove('show');
    document.body.classList.remove('has-cookie-banner');
  }
  if(consent === 'accepted') loadAnalytics();
  else if(consent !== 'rejected'){ setTimeout(showBanner, 1500); }
  document.getElementById('cookieAccept').addEventListener('click', ()=>{
    try{ localStorage.setItem('icm-consent','accepted'); }catch(e){}
    hideBanner(); loadAnalytics();
  });
  document.getElementById('cookieReject').addEventListener('click', ()=>{
    try{ localStorage.setItem('icm-consent','rejected'); }catch(e){}
    hideBanner();
    window.dataLayer = window.dataLayer || [];
  });

  /* === GOOGLE REVIEWS — fetch from Cloudflare Worker === */
  /* Set this to your deployed Worker URL. Falls back to static reviews if fetch fails. */
  const REVIEWS_ENDPOINT = (window.ICM_REVIEWS_ENDPOINT) || 'https://icm-reviews.vg-ab6.workers.dev/';
  const REVIEWS_LS_KEY = 'icm-reviews-cache-v1';
  const REVIEWS_LS_TTL = 12 * 60 * 60 * 1000; // 12h browser-side cache

  function getCachedReviews(){
    try{
      const raw = localStorage.getItem(REVIEWS_LS_KEY);
      if(!raw) return null;
      const obj = JSON.parse(raw);
      if(Date.now() - obj._t > REVIEWS_LS_TTL) return null;
      return obj.data;
    }catch(e){ return null; }
  }
  function setCachedReviews(data){
    try{ localStorage.setItem(REVIEWS_LS_KEY, JSON.stringify({_t: Date.now(), data})); }catch(e){}
  }

  function starsSvg(n, total){
    let html = '';
    for(let i=1; i<=total; i++){
      html += `<svg viewBox="0 0 24 24" class="${i<=n?'':'dim'}"><path d="M12 2l3 7h7l-5.5 4.5L18 21l-6-4-6 4 1.5-7.5L2 9h7z"/></svg>`;
    }
    return html;
  }

  function initials(name){
    if(!name) return 'IC';
    const parts = name.trim().split(/\s+/);
    return ((parts[0]?.[0]||'') + (parts[1]?.[0]||'')).toUpperCase() || 'IC';
  }

  function escapeHtml(s){
    return String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function truncate(s, n){
    s = String(s||'').trim();
    if(s.length <= n) return s;
    return s.slice(0, n).replace(/\s+\S*$/,'') + '…';
  }

  function renderReviews(data){
    if(!data || !data.reviews || !data.reviews.length) return false;

    // Summary block
    const summary = document.getElementById('reviewsSummary');
    if(summary && typeof data.rating === 'number'){
      document.getElementById('rsRating').textContent = data.rating.toFixed(1);
      document.getElementById('rsStars').innerHTML = starsSvg(Math.round(data.rating), 5);
      document.getElementById('rsTotal').textContent = data.total || data.reviews.length;
      summary.removeAttribute('hidden');
    }

    // Reviews row — render up to 3 best
    const row = document.getElementById('reviewsRow');
    if(row){
      // Pick up to 3 reviews — prefer 5-star with longest text
      const sorted = [...data.reviews].sort((a,b)=>{
        const ra = (a.rating||0) - (b.rating||0);
        if(ra !== 0) return -ra;
        return (b.text?.length||0) - (a.text?.length||0);
      });
      const picks = sorted.slice(0, 3);
      row.innerHTML = picks.map(r => `
        <article class="review">
          <div class="stars">${starsSvg(Math.round(r.rating||5), 5)}</div>
          <p>&ldquo;${escapeHtml(truncate(r.text, 380))}&rdquo;</p>
          <div class="author">
            ${r.avatar ? `<img class="avatar" src="${escapeHtml(r.avatar)}" alt="${escapeHtml(r.author)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.outerHTML='<div class=&quot;avatar&quot;>${initials(r.author)}</div>'" />` : `<div class="avatar">${initials(r.author)}</div>`}
            <div class="author-info">
              <span class="name">${escapeHtml(r.author)}</span>
              <span class="role">${escapeHtml(r.when || 'Google review')}</span>
            </div>
          </div>
        </article>
      `).join('');
      // Mark as already revealed since reveal observer already handled this row before
      row.classList.add('in');
    }

    // Footer CTA
    const foot = document.getElementById('reviewsFoot');
    if(foot) foot.removeAttribute('hidden');

    return true;
  }

  async function loadReviews(){
    // Try local cache first — instant render
    const cached = getCachedReviews();
    if(cached){ renderReviews(cached); }

    try{
      const resp = await fetch(REVIEWS_ENDPOINT, { cache: 'no-store' });
      if(!resp.ok) return;
      const data = await resp.json();
      if(data && data.reviews && data.reviews.length){
        setCachedReviews(data);
        renderReviews(data);
      }
    }catch(e){
      // fail silently — keep static fallback / cached version
    }
  }
  // Lazy-load: fetch only when user scrolls near reviews section
  const reviewsSection = document.getElementById('reviews');
  if(reviewsSection){
    const ro = new IntersectionObserver((entries)=>{
      for(const e of entries){
        if(e.isIntersecting){
          loadReviews();
          ro.disconnect();
          break;
        }
      }
    }, {rootMargin: '300px 0px'});
    ro.observe(reviewsSection);
  }

  /* Smooth-scroll fallback for #anchors with header offset */
  document.querySelectorAll('a[href^="#"]').forEach(a=>{
    a.addEventListener('click', e=>{
      const href = a.getAttribute('href');
      if(href === '#' || href.length<2) return;
      const target = document.querySelector(href);
      if(!target) return;
      e.preventDefault();
      const top = target.getBoundingClientRect().top + window.scrollY - 70;
      window.scrollTo({top, behavior:'smooth'});
    });
  });
});